const type = $json.body.type;
const title = $json.body.title;
const email = $json.body.email || "Not provided";
const fields = $json.body.fields;

let github_title, github_labels, github_body;

switch(type) {
  case "bug":
    github_title = `[Bug]: ${title}`;
    github_labels = "bug";
    github_body = `**What happened?**
${fields.description}

**Expected behavior**
${fields.expected}

**Page URL**
${fields.url || "Not provided"}

**Device**
${fields.device || "Not provided"}

**Browser**
${fields.browser || "Not provided"}

**Reporter email**
${email}`;
    break;
  case "data":
    github_title = `[Data]: ${title}`;
    github_labels = "data-correction";
    github_body = `**Where is the error?**
${fields.location}

**Current (incorrect) value**
${fields.current_value}

**Correct value**
${fields.correct_value}

**Source**
${fields.sources}

**Reporter email**
${email}`;
    break;
  case "feature":
    github_title = `[Feature]: ${title}`;
    github_labels = "enhancement";
    github_body = `**What would you like?**
${fields.description}

**Why?**
${fields.motivation || "Not provided"}

**Reporter email**
${email}`;
    break;
  case "tax":
    github_title = `[Tax]: ${title}`;
    github_labels = "tax-suggestion";
    github_body = `**Tax name**
${fields.tax_name}

**Description**
${fields.description}

**Sources**
${fields.sources}

**Reporter email**
${email}`;
    break;
  default:
    throw new Error(`Unknown type: ${type}`);
}

return {
  github_title,
  github_labels,
  github_body
};
